fn percentile(sorted: &[f32], q: f32) -> f32 {
    if sorted.is_empty() {
        return 0.0;
    }
    let q = if q.is_finite() { q.clamp(0.0, 1.0) } else { 0.5 };
    sorted.get(((sorted.len() - 1) as f32 * q) as usize).copied().unwrap_or(0.0)
}

